package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import com.lqq.supportflow.shared.ConflictException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RegisterKnowledgeDocumentService { private final KnowledgeDocumentPort documents; private final KnowledgeBasePort knowledgeBases; public RegisterKnowledgeDocumentService(KnowledgeDocumentPort documents,KnowledgeBasePort knowledgeBases){this.documents=documents;this.knowledgeBases=knowledgeBases;} @Transactional public KnowledgeDocument register(Long t,Long b,String f,String content){if(!knowledgeBases.belongsTo(t,b))throw new IllegalArgumentException("knowledge base does not belong to tenant");String h=ContentHasher.sha256(content);if(documents.exists(t,b,h))throw new ConflictException("duplicate document content");return documents.save(t,b,f,h);}}
